  "app.setPayments.financingDesc": "ਗਾਹਕਾਂ ਨੂੰ ਕਾਰਡ ਨਾਲ ਭੁਗਤਾਨ ਦੇ ਨਾਲ-ਨਾਲ ਚੈੱਕਆਊਟ 'ਤੇ Affirm ਰਾਹੀਂ ਇਨਵੌਇਸ ਨੂੰ ਕਿਸ਼ਤਾਂ ਵਿੱਚ ਵੰਡਣ ਦਿਓ। ਤੁਹਾਨੂੰ ਪੂਰੀ ਰਕਮ ਪਹਿਲਾਂ ਹੀ ਮਿਲ ਜਾਂਦੀ ਹੈ — ਬਾਕੀ Affirm ਸੰਭਾਲਦਾ ਹੈ।",
  "app.setPayments.financingActivateNote": "USD ਜਾਂ CAD ਵਿੱਚ $50 ਤੋਂ $30,000 ਦੇ ਵਿਚਕਾਰ ਦੇ ਇਨਵੌਇਸਾਂ 'ਤੇ ਉਪਲਬਧ। ਪਹਿਲਾਂ ਤੁਹਾਨੂੰ ਆਪਣੇ Stripe ਡੈਸ਼ਬੋਰਡ ਵਿੱਚ Affirm ਨੂੰ ਸਰਗਰਮ ਕਰਨਾ ਪਵੇਗਾ।",
  "app.setPayments.financingSaveError": "ਤੁਹਾਡੀ ਵਿੱਤ ਸੈਟਿੰਗ ਸੰਭਾਲੀ ਨਹੀਂ ਜਾ ਸਕੀ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "app.quoteImports.title": "ਕਿਸੇ ਹੋਰ ਕੰਪਨੀ ਦੇ ਹਵਾਲੇ ਵਿੱਚ ਵਰਤਿਆ ਗਿਆ",
  "app.quoteImports.subtitle": "ਇੱਕ ਠੇਕੇਦਾਰ ਨੇ ਇਹ ਹਵਾਲਾ ਆਪਣੇ ਪ੍ਰੋਜੈਕਟ ਵਿੱਚ ਲਾਗਤ ਵਜੋਂ ਜੋੜਿਆ ਹੈ। ਜਦੋਂ ਉਸਦਾ ਗਾਹਕ ਉਸਦੇ ਹਵਾਲੇ ਨੂੰ ਮਨਜ਼ੂਰ ਕਰੇਗਾ ਤਾਂ ਤੁਹਾਡੀ ਪੁਸ਼ਟੀ ਹੋ ਜਾਵੇਗੀ।",
