  "app.setBooking.bufferHint": "ਗੱਡੀ ਚਲਾਉਣ ਦੇ ਸਮੇਂ ਤੋਂ ਉੱਪਰ ਜੋੜਿਆ ਜਾਂਦਾ ਹੈ — ਪਾਰਕਿੰਗ, ਉਤਾਰਨਾ, ਪਿਛਲੇ ਕੰਮ ਦਾ ਲੇਖਾ ਲਿਖਣਾ। ਸਿਫ਼ਰ ਤੋਂ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ, ਕਿਉਂਕਿ ਤੁਹਾਡੇ ਵੱਲੋਂ ਅੰਦਾਜ਼ਾ ਲਾਉਣਾ ਉਹ ਬੁੱਕ ਹੋਣ ਯੋਗ ਸਲਾਟ ਹਟਾ ਦੇਵੇਗਾ ਜੋ ਤੁਸੀਂ ਛੱਡਣ ਲਈ ਕਦੇ ਸਹਿਮਤ ਨਹੀਂ ਹੋਏ।",
