  "app.setBooking.promiseHint": "ਸਮਾਂ-ਵਿੰਡੋ ਇੱਕ ਅਜਿਹਾ ਵਾਅਦਾ ਹੈ ਜਿਸ ਨੂੰ ਸੜਕ ਤੋੜ ਨਹੀਂ ਸਕਦੀ। ਤੁਹਾਡਾ ਆਪਣਾ ਸ਼ਡਿਊਲ ਹਰ ਹਾਲ ਵਿੱਚ ਸਹੀ ਸਮਾਂ ਰੱਖਦਾ ਹੈ — ਇਹ ਸਿਰਫ਼ ਇਹ ਬਦਲਦਾ ਹੈ ਕਿ ਕਲਾਇੰਟ ਨੂੰ ਕੀ ਦੱਸਿਆ ਜਾਂਦਾ ਹੈ।",
