  "app.setBooking.changesHint": "ਬੁੱਕ ਕੀਤੀ ਮੁਲਾਕਾਤ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਨੂੰ ਕਿੰਨੀ ਪੇਸ਼ਗੀ ਸੂਚਨਾ ਚਾਹੀਦੀ ਹੈ, ਅਤੇ ਜੇ ਗਾਹਕ ਸਮੇਂ ਸਿਰ ਰੱਦ ਕਰੇ ਤਾਂ ਮੁਲਾਕਾਤ ਫ਼ੀਸ ਦਾ ਕੀ ਹੁੰਦਾ ਹੈ।",
