  "app.setVoice.portedCta": "ਪੋਰਟ ਸ਼ੁਰੂ ਕਰੋ",
  "app.setVoice.portedNote": "ਤੁਹਾਡੇ ਮੌਜੂਦਾ ਪ੍ਰਦਾਤਾ ਨੂੰ ਕੀ ਚਾਹੀਦਾ ਹੈ ਅਸੀਂ ਤੁਹਾਨੂੰ ਈਮੇਲ ਕਰਾਂਗੇ। ਤੁਹਾਡਾ ਮੌਜੂਦਾ ਨੰਬਰ ਸਾਰਾ ਸਮਾਂ ਚੱਲਦਾ ਰਹਿੰਦਾ ਹੈ, ਅਤੇ ਟ੍ਰਾਂਸਫਰ ਪੂਰਾ ਹੋਣ ਤੱਕ ਕੁਝ ਨਹੀਂ ਬਦਲਦਾ।",
