  "app.setVoice.firstMonthNow": "{amount} — ਪਹਿਲਾ ਮਹੀਨਾ — ਹੁਣੇ ਤੁਹਾਡੇ ਕ੍ਰੈਡਿਟ ਵਿੱਚੋਂ ਲਿਆ ਜਾਂਦਾ ਹੈ।",
  "app.setVoice.firstMonthUpFront": "ਜਿਵੇਂ ਹੀ ਤੁਸੀਂ ਕੋਈ ਚੁਣਦੇ ਹੋ, ਪਹਿਲੇ ਮਹੀਨੇ ਦਾ ਕਿਰਾਇਆ ਤੁਹਾਡੇ ਕ੍ਰੈਡਿਟ ਵਿੱਚੋਂ ਲਿਆ ਜਾਂਦਾ ਹੈ।",
  "app.setVoice.cantAfford": "ਪਹਿਲਾਂ {amount} ਹੋਰ ਕ੍ਰੈਡਿਟ ਪਾਓ — ਪਹਿਲੇ ਮਹੀਨੇ ਦਾ {rental} ਕਿਰਾਇਆ ਪਹਿਲਾਂ ਹੀ ਲਿਆ ਜਾਂਦਾ ਹੈ।",
  "app.setVoice.trialWithNumber": "ਤੁਹਾਡੇ ਪਹਿਲੇ ਨੰਬਰ ਨਾਲ {minutes} ਮੁਫ਼ਤ ਮਿੰਟ ਤੁਹਾਡੇ ਕ੍ਰੈਡਿਟ ਵਿੱਚ ਜੁੜ ਜਾਂਦੇ ਹਨ।",
  "app.setVoice.portNoCharge": "ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਕੁਝ ਨਹੀਂ ਲਿਆ ਜਾਂਦਾ। ਮਾਸਿਕ ਕਿਰਾਇਆ ਸਿਰਫ਼ ਉਦੋਂ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਨੰਬਰ ਅਸਲ ਵਿੱਚ ਤਬਦੀਲ ਹੋ ਜਾਂਦਾ ਹੈ।",
  "app.setVoice.rentNext": "ਅਗਲਾ ਕਿਰਾਇਆ {amount}, {date} ਨੂੰ, ਉੱਪਰਲੇ ਕ੍ਰੈਡਿਟ ਵਿੱਚੋਂ।",
  "app.setVoice.rentSoon": "ਇਹ ਨੰਬਰ ਚਾਲੂ ਹੁੰਦੇ ਹੀ {amount} ਮਾਸਿਕ ਕਿਰਾਇਆ ਉੱਪਰਲੇ ਕ੍ਰੈਡਿਟ ਵਿੱਚੋਂ ਜਾਣ ਲੱਗੇਗਾ।",
  "app.setVoice.rentWontCover": "ਤੁਹਾਡਾ ਬਕਾਇਆ ਪੂਰਾ ਨਹੀਂ ਪਵੇਗਾ — ਉਸ ਤੋਂ ਪਹਿਲਾਂ ਟਾਪ-ਅੱਪ ਕਰੋ।",
  "app.setVoice.rentPastDueTitle": "ਇਸ ਨੰਬਰ ਦਾ ਕਿਰਾਇਆ ਅਦਾ ਨਹੀਂ ਹੋਇਆ",
  "app.setVoice.rentPastDueDated": "ਇਹ {date} ਤੱਕ ਚੱਲਦਾ ਰਹੇਗਾ। ਉਸ ਤੋਂ ਬਾਅਦ ਨੰਬਰ ਛੱਡ ਦਿੱਤਾ ਜਾਵੇਗਾ ਅਤੇ ਤੁਸੀਂ ਇਸਨੂੰ ਗੁਆ ਦਿਓਗੇ — ਇਸਨੂੰ ਰੱਖਣ ਲਈ ਕ੍ਰੈਡਿਟ ਪਾਓ।",
  "app.setVoice.rentPastDueNow": "{amount} ਕਿਰਾਇਆ ਹੁਣ ਬਕਾਇਆ ਹੈ ਅਤੇ ਤੁਹਾਡਾ ਬਕਾਇਆ ਪੂਰਾ ਨਹੀਂ ਪੈਂਦਾ। ਨੰਬਰ ਰੱਖਣ ਲਈ ਕ੍ਰੈਡਿਟ ਪਾਓ — ਕੁਝ ਵੀ ਛੱਡਣ ਤੋਂ ਪਹਿਲਾਂ ਅਸੀਂ ਤੁਹਾਨੂੰ ਈਮੇਲ ਕਰਾਂਗੇ।",
