  "app.setInstantQuotes.financingIntro": "ਵਿਕਲਪਿਕ। FieldQuo ਵਿੱਤ ਮੁਹੱਈਆ ਨਹੀਂ ਕਰਦਾ ਅਤੇ ਕਦੇ ਮਹੀਨਾਵਾਰ ਰਕਮ ਨਹੀਂ ਦਿਖਾਉਂਦਾ — ਇਹ ਸਿਰਫ਼ ਘਰ-ਮਾਲਕਾਂ ਨੂੰ ਦੱਸਦਾ ਹੈ ਕਿ ਇਹ ਉਪਲਬਧ ਹੈ, ਤੁਹਾਡੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਜਾਂ ਤੁਹਾਡੇ ਪ੍ਰਦਾਤਾ ਰਾਹੀਂ।",
