  "app.setInstantQuotes.providerLinkHelp": "ਜੇ ਸੈੱਟ ਕੀਤਾ, ਘਰ-ਮਾਲਕਾਂ ਨੂੰ ਤੁਹਾਡੇ ਪ੍ਰਦਾਤਾ ਲਈ ਇੱਕ ਬਟਨ ਮਿਲਦਾ ਹੈ, ਜੋ ਸ਼ਰਤਾਂ ਦੱਸਦਾ ਹੈ। \"ਸਾਨੂੰ ਪੁੱਛੋ\" ਲਈ ਖਾਲੀ ਛੱਡੋ।",
