  "app.siteBuilder.example1": "ਦਲੇਰ ਅਤੇ ਉਦਯੋਗਿਕ। ਸਾਡੀਆਂ ਪਹਿਲਾਂ-ਬਾਅਦ ਦੀਆਂ ਫ਼ੋਟੋਆਂ ਨਾਲ ਸ਼ੁਰੂ ਕਰੋ — ਅਸੀਂ ਸ਼ਹਿਰ ਦੀ ਸਭ ਤੋਂ ਵੱਡੀ ਟੀਮ ਵਾਂਗ ਦਿਸਣਾ ਚਾਹੁੰਦੇ ਹਾਂ।",
