  "app.reviewsEmbed.heading": "ਤੁਹਾਡੀ ਆਪਣੀ ਵੈੱਬਸਾਈਟ 'ਤੇ ਤੁਹਾਡੀਆਂ ਸਮੀਖਿਆਵਾਂ",
  "app.reviewsEmbed.frameTitle": "ਗਾਹਕਾਂ ਦੀਆਂ ਸਮੀਖਿਆਵਾਂ",
  "app.reviewsEmbed.note": "ਇਸਨੂੰ ਉਸ ਵੈੱਬਸਾਈਟ ਵਿੱਚ ਪੇਸਟ ਕਰੋ ਜੋ ਤੁਹਾਡੇ ਕੋਲ ਪਹਿਲਾਂ ਹੀ ਹੈ। ਇਹ ਤੁਹਾਡੀਆਂ ਮਨਜ਼ੂਰ ਕੀਤੀਆਂ ਸਮੀਖਿਆਵਾਂ ਤੁਹਾਡੇ ਆਪਣੇ ਰੰਗਾਂ ਵਿੱਚ ਦਿਖਾਉਂਦਾ ਹੈ, ਬਿਨਾਂ ਕਿਸੇ FieldQuo ਬ੍ਰਾਂਡਿੰਗ ਦੇ। ਜਦੋਂ ਤੱਕ ਕੋਈ ਸਮੀਖਿਆ ਨਹੀਂ ਹੁੰਦੀ, ਇਹ ਕੁਝ ਵੀ ਨਹੀਂ ਦਿਖਾਉਂਦਾ ਅਤੇ ਉਚਾਈ ਵਿੱਚ ਸਿਫ਼ਰ ਹੋ ਜਾਂਦਾ ਹੈ — ਇਸ ਲਈ ਇਸਨੂੰ ਪਹਿਲਾਂ ਹੀ ਲਗਾਉਣਾ ਸੁਰੱਖਿਅਤ ਹੈ। ਸਕ੍ਰਿਪਟ ਨੂੰ iframe ਨਾਲ ਰੱਖੋ: ਇਹੀ ਬਾਕਸ ਦਾ ਆਕਾਰ ਤੈਅ ਕਰਦੀ ਹੈ।",
  "app.siteBuilder.sections": "ਭਾਗ",
  "app.siteBuilder.device.desktop": "ਡੈਸਕਟਾਪ",
  "app.siteBuilder.device.mobile": "ਮੋਬਾਈਲ",
  "app.siteBuilder.refreshPreview": "ਝਲਕ ਤਾਜ਼ਾ ਕਰੋ",
  "app.siteBuilder.saveOnce": "ਇੱਕ ਵਾਰ ਸੰਭਾਲੋ ਅਤੇ ਤੁਹਾਡੀ ਸਾਈਟ ਇੱਥੇ ਦਿਖਾਈ ਦੇਵੇਗੀ।",
  "app.siteBuilder.sectionsNote": "ਕੁਝ ਵੀ ਹੱਥੀਂ ਦੁਬਾਰਾ ਲਿਖੋ। ਤੁਹਾਡਾ ਲੋਗੋ, ਰੰਗ, ਸੇਵਾਵਾਂ, ਘੰਟੇ ਅਤੇ ਸੰਪਰਕ ਵੇਰਵੇ ਤੁਹਾਡੀ ਕੰਪਨੀ ਸੈਟਿੰਗਾਂ ਤੋਂ ਆਉਂਦੇ ਹਨ ਅਤੇ ਇੱਥੇ ਸੋਧੇ ਨਹੀਂ ਜਾ ਸਕਦੇ — ਉੱਥੇ ਬਦਲਣ ਨਾਲ ਸਾਈਟ ਅੱਪਡੇਟ ਹੁੰਦੀ ਹੈ।",
  "app.siteBuilder.openPreview": "ਝਲਕ ਖੋਲ੍ਹੋ",
  "app.siteBuilder.regenTitle": "ਇਹ ਉਹ ਸ਼ਬਦ ਦੁਬਾਰਾ ਲਿਖ ਦੇਵੇਗਾ ਜੋ ਤੁਸੀਂ ਸੋਧੇ ਸਨ",
  "app.siteBuilder.regenBody": "ਤੁਸੀਂ ਕੁਝ ਲਿਖਤ ਹੱਥੀਂ ਬਦਲੀ ਸੀ। ਦੁਬਾਰਾ ਬਣਾਉਣ ਨਾਲ ਹਰ ਭਾਗ ਲਈ ਨਵੀਂ ਲਿਖਤ ਲਿਖੀ ਜਾਂਦੀ ਹੈ, ਇਸ ਲਈ ਉਹ ਸੋਧਾਂ ਬਦਲ ਜਾਣਗੀਆਂ।",
  "app.siteBuilder.regenKept": "ਤੁਹਾਡੀਆਂ ਫ਼ੋਟੋਆਂ, ਪਹਿਲਾਂ-ਬਾਅਦ ਦੇ ਜੋੜੇ, ਲੋਗੋ ਅਤੇ ਰੰਗ ਰੱਖੇ ਜਾਂਦੇ ਹਨ",
  "app.siteBuilder.regenRewritten": "ਤੁਹਾਡੇ ਵੱਲੋਂ ਟਾਈਪ ਕੀਤੇ ਸਿਰਲੇਖ ਅਤੇ ਪੈਰੇ ਦੁਬਾਰਾ ਲਿਖੇ ਜਾਣਗੇ",
  "app.siteBuilder.keepWhatIWrote": "ਜੋ ਮੈਂ ਲਿਖਿਆ ਉਹ ਰੱਖੋ",
  "app.siteBuilder.rebuildAnyway": "ਫਿਰ ਵੀ ਦੁਬਾਰਾ ਬਣਾਓ",
  "app.siteBuilder.stockPhotosTitle": "ਤੁਹਾਡੀ ਸਾਈਟ 'ਤੇ ਅਜੇ ਵੀ {count} ਸਟਾਕ ਫ਼ੋਟੋ",
  "app.siteBuilder.stockPhotosBody1": "ਮੈਂ ਸਟਾਕ ਫ਼ੋਟੋਗ੍ਰਾਫ਼ੀ ਵਰਤੀ ਤਾਂ ਜੋ ਤੁਹਾਡਾ ਪੰਨਾ ਖਾਲੀ ਨਾ ਹੋਵੇ। ਇਹ ਸਿਰਫ਼ ਹੈੱਡਰ ਦੇ ਪਿਛੋਕੜ ਅਤੇ ਅਜਿਹੀਆਂ ਥਾਵਾਂ 'ਤੇ ਹੈ — ਕਦੇ ਵੀ «ਸਾਡਾ ਕੰਮ» ਵਿੱਚ ਨਹੀਂ, ਕਿਉਂਕਿ ਉਹ ਭਾਗ ਕਹਿੰਦਾ ਹੈ ਕਿ ਫ਼ੋਟੋਆਂ ਤੁਹਾਡੇ ਕੀਤੇ ਕੰਮ ਹਨ।",
  "app.siteBuilder.stockPhotosBody2": "ਤੁਸੀਂ ਹੁਣ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰ ਸਕਦੇ ਹੋ ਅਤੇ ਬਾਅਦ ਵਿੱਚ ਬਦਲ ਸਕਦੇ ਹੋ, ਜਾਂ ਪਹਿਲਾਂ ਆਪਣੀਆਂ ਫ਼ੋਟੋਆਂ ਸ਼ਾਮਲ ਕਰੋ — ਤੁਹਾਡਾ ਆਪਣਾ ਕੰਮ ਹਮੇਸ਼ਾ ਸਟਾਕ ਹਾਊਸ ਨਾਲੋਂ ਵਧੀਆ ਵਿਕਦਾ ਹੈ।",
